changeSet.sql:
CREATE INDEX idx_login_attempts_ownerless_age
    ON login_attempts (COALESCE(time_stamp, created_at)) WHERE user_id IS NULL;
CREATE INDEX idx_login_attempts_attributed_age
    ON login_attempts (COALESCE(time_stamp, created_at)) WHERE user_id IS NOT NULL;
CREATE INDEX idx_login_attempts_ownerless_email
    ON login_attempts (LOWER(email_attempted)) WHERE user_id IS NULL;

rollback.sql:
DROP INDEX idx_login_attempts_ownerless_age;
DROP INDEX idx_login_attempts_attributed_age;
DROP INDEX idx_login_attempts_ownerless_email;
